using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StockFlow.Data;
using StockFlow.Models;
namespace StockFlow.Controllers; [Authorize(Roles = "Admin")] public class AdminController(UserManager<ApplicationUser> users, ApplicationDbContext db) : Controller { public async Task<IActionResult> Users() => View(await users.Users.OrderBy(u => u.Email).ToListAsync()); [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> ToggleActive(string id) { var u = await users.FindByIdAsync(id); if (u == null) return NotFound(); if (u.Email == User.Identity?.Name) { TempData["Error"] = "You cannot deactivate your own account."; return RedirectToAction(nameof(Users)); } u.IsActive = !u.IsActive; await users.UpdateAsync(u); db.AuditLogs.Add(new AuditLog { UserEmail = User.Identity?.Name ?? "admin", Action = u.IsActive ? "Activated user" : "Deactivated user", EntityName = "ApplicationUser", EntityId = u.Id, Details = u.Email ?? "" }); await db.SaveChangesAsync(); TempData["Success"] = "User status updated."; return RedirectToAction(nameof(Users)); } [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> SetRole(string id, string role) { var allowed = new[] { "Admin", "Manager", "StockClerk", "Procurement", "Viewer" }; if (!allowed.Contains(role)) return BadRequest(); var u = await users.FindByIdAsync(id); if (u == null) return NotFound(); var current = await users.GetRolesAsync(u); await users.RemoveFromRolesAsync(u, current); await users.AddToRoleAsync(u, role); db.AuditLogs.Add(new AuditLog { UserEmail = User.Identity?.Name ?? "admin", Action = "Role changed", EntityName = "ApplicationUser", EntityId = u.Id, Details = $"{u.Email}: {role}" }); await db.SaveChangesAsync(); TempData["Success"] = "Role updated."; return RedirectToAction(nameof(Users)); } }
